@extends('layouts.app') @section('title','Quản lý đơn hàng') @section('content')<section class="section"><span class="eyebrow">ADMIN · ORDERS</span><h1>Quản lý đơn hàng</h1><div class="table-scroll"><table class="admin-table"><thead><tr><th>Mã đơn</th><th>Khách hàng</th><th>Tổng tiền</th><th>Thanh toán</th><th>Trạng thái</th><th>Cập nhật</th></tr></thead><tbody>@foreach($orders as $o)<tr><td>{{ $o->order_code }}</td><td>{{ $o->user->name }}<br>{{ $o->phone }}</td><td>{{ number_format($o->total_amount,0,',','.') }}đ</td><td>{{ $o->payment_status }}</td><td>{{ $o->status }}</td><td><form method="POST" action="{{ route('admin.orders.update',$o) }}">@csrf @method('PATCH')<select name="status">@foreach(['pending'=>'Chờ xác nhận','confirmed'=>'Đã xác nhận','shipping'=>'Đang giao','delivered'=>'Đã giao','cancelled'=>'Đã hủy'] as $val=>$label)<option value="{{ $val }}" @selected($o->status===$val)>{{ $label }}</option>@endforeach</select><button class="btn btn-small btn-primary">Lưu</button></form></td></tr>@endforeach</tbody></table></div>{{ $orders->links() }}</section>@endsection